<script setup>
import {onMounted,ref} from 'vue';import {useRouter} from 'vue-router';import {ElMessage} from 'element-plus';import api,{messageOf} from '../../api/request.js';
const courses=ref([]),dialog=ref(false),code=ref(''),router=useRouter();async function load(){try{courses.value=(await api.get('/my/courses')).data}catch(e){ElMessage.error(messageOf(e))}}async function join(){try{await api.post('/courses/join',{invite_code:code.value});ElMessage.success('已加入课程');dialog.value=false;code.value='';load()}catch(e){ElMessage.error(messageOf(e))}}onMounted(load);
</script>
<template><div><div class="page-head"><div><span class="badge">学生空间</span><h1>我的课程</h1><p>查看进行中的作业与提交记录</p></div><el-button type="primary" color="#15554e" @click="dialog=true">输入邀请码</el-button></div><div v-if="courses.length" class="course-grid"><article v-for="c in courses" :key="c.id" class="course-card" @click="router.push(`/student/courses/${c.id}`)"><span class="badge">{{c.code||'课程'}}</span><h3>{{c.name}}</h3><p>{{c.description||'点击查看课程作业'}}</p><div class="meta-row"><span>{{c.assignment_count}} 项进行中作业</span><span>进入课程 →</span></div></article></div><div v-else class="panel empty"><h3>还没有加入课程</h3><p>向老师获取6位邀请码后加入。</p></div><el-dialog v-model="dialog" title="加入课程" width="min(420px,92vw)"><el-input v-model="code" maxlength="6" size="large" placeholder="请输入6位邀请码" style="text-transform:uppercase"/><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" color="#15554e" @click="join">加入</el-button></template></el-dialog></div></template>
